// Generates docs/sql-index.md: every per-table query module in src/server/sql
// with its exported functions, so an agent can find an existing query before
// writing a new one. `--check` fails when the checked-in index is stale.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { parseSync } from "rolldown/utils";

const header = [
  "# SQL query modules",
  "",
  "Generated by `npm run sql-index` from [src/server/sql](../src/server/sql/); do not edit by hand. Search this before adding a query, and extend the module that owns the table. The [SQL recipe](architecture.md#recipe-add-or-extend-a-sql-table-module) describes the pattern.",
  "",
];

// First sentence of a /** */ comment that ends directly before the export.
function summary(text, comments, start) {
  const comment = comments
    .filter((c) => c.type === "Block" && c.value.startsWith("*"))
    .find((c) => c.end <= start && !text.slice(c.end, start).trim());
  if (!comment) return null;
  const prose = comment.value
    .replace(/^\*/, "")
    .split("\n")
    .map((line) => line.replace(/^\s*\*\s?/, "").trim())
    .join(" ")
    .trim();
  const sentence = /^(.+?[.!?])(\s|$)/.exec(prose)?.[1] ?? prose;
  return sentence ? sentence.replace(/\s+/g, " ") : null;
}

function exportedFunctions(file, text) {
  const { program, comments, errors } = parseSync(file, text);
  if (errors.length) throw new Error(`${file}: ${errors[0].message}`);
  const found = [];
  for (const node of program.body) {
    if (node.type !== "ExportNamedDeclaration" || !node.declaration) continue;
    const declaration = node.declaration;
    const entries =
      declaration.type === "FunctionDeclaration"
        ? [[declaration.id.name, declaration.params]]
        : declaration.type === "VariableDeclaration"
          ? declaration.declarations
              .filter((d) =>
                ["ArrowFunctionExpression", "FunctionExpression"].includes(
                  d.init?.type,
                ),
              )
              .map((d) => [d.id.name, d.init.params])
          : [];
    for (const [name, params] of entries)
      found.push({
        name,
        params: params.map((param) =>
          param.type === "AssignmentPattern"
            ? `${param.left.name ?? "…"}?`
            : param.type === "RestElement"
              ? `...${param.argument.name ?? "…"}`
              : param.type === "Identifier"
                ? `${param.name}${param.optional ? "?" : ""}`
                : "{…}",
        ),
        summary: summary(text, comments, node.start),
      });
  }
  return found.sort((a, b) => a.name.localeCompare(b.name));
}

/** Markdown for every module in `directory`, links relative to docs/. */
export function sqlIndex(directory, linkBase = "../src/server/sql") {
  const lines = [...header];
  let missing = 0;
  const modules = readdirSync(directory)
    .filter((name) => name.endsWith(".ts"))
    .sort();
  for (const module of modules) {
    const functions = exportedFunctions(
      join(directory, module),
      readFileSync(join(directory, module), "utf8"),
    );
    if (!functions.length) continue;
    lines.push(`## [${module}](${linkBase}/${module})`, "");
    for (const fn of functions) {
      if (!fn.summary) missing++;
      lines.push(
        `- \`${fn.name}(${fn.params.join(", ")})\`${fn.summary ? ` — ${fn.summary}` : ""}`,
      );
    }
    lines.push("");
  }
  return { text: lines.join("\n").replace(/\n+$/, "\n"), missing };
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(process.argv[1]).href
) {
  const root = fileURLToPath(new URL("..", import.meta.url));
  const target = join(root, "docs/sql-index.md");
  const { text, missing } = sqlIndex(join(root, "src/server/sql"));
  if (process.argv.includes("--check")) {
    if (readFileSync(target, "utf8") !== text) {
      console.error("docs/sql-index.md is stale: run npm run sql-index");
      process.exitCode = 1;
    } else console.log("SQL index matches src/server/sql");
  } else {
    writeFileSync(target, text);
    console.log(
      `Wrote docs/sql-index.md (${text.length} bytes; ${missing} functions without a doc comment)`,
    );
  }
}
